//! 🧪️ Recursive Value children retain exact tags and UTF8 drafts through original copying and close.
use super::*;
use semio_framework_plugin::app_testing::OriginalWorkFixture;
fn source(kind:InputKind)->DslValue{let raw="-".repeat(63)+"€"+&"ä".repeat(40);let child=if kind==InputKind::List{DslValue::Object(vec![("kind".into(),DslValue::String("aggregate".into())),("value".into(),DslValue::Array([raw,"-2".into(),"-3".into()].into_iter().map(|word|DslValue::Object(vec![("kind".into(),DslValue::String("integer".into())),("value".into(),DslValue::String(word))])).collect()))])}else{DslValue::Object(vec![("kind".into(),DslValue::String(kind.tag().into())),("value".into(),DslValue::String(raw))])};DslValue::Object(vec![("name".into(),DslValue::String(name(kind).into())),("items".into(),DslValue::Array(vec![child]))])}
fn name(kind:InputKind)->&'static str{match kind{InputKind::Enum=>"IFCLOGICAL",InputKind::Binary=>"IFCBINARY",InputKind::List=>"IFCCOMPOUNDPLANEANGLEMEASURE",_=>panic!("closed Value child law")}}
#[test]
fn original_value_children_preserve_all_raw_words_with_pure_quotes_and_every_denied_axis(){for kind in [InputKind::Enum,InputKind::Binary,InputKind::List]{let source=source(kind);let input=Input{source:Some(&source),name:name(kind),kind,fill:false};let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());let mut output=None;for turn in 0..100000{let demand=copy.as_ref().unwrap().demands(&input).unwrap();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||copy.as_ref().unwrap().demands(&input));assert_eq!(answer.unwrap(),demand);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for axis in 0..6{let mut denied=OriginalWorkFixture::stock();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&input,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).unwrap(){break;}assert!(turn<99999);}assert!(caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().take(&mut output,cx)).unwrap());assert_eq!(output.as_ref(),Some(&source));super::set_tests::retire(&mut caller,&mut copy);super::set_tests::retire(&mut caller,&mut output);caller.finish();}}
#[test]
fn original_value_children_retire_every_cancelled_constructor_prefix(){for kind in [InputKind::Enum,InputKind::Binary,InputKind::List]{let source=source(kind);let input=Input{source:Some(&source),name:name(kind),kind,fill:false};let mut total=None;for prefix in std::iter::once(None).chain((0..100000).map(Some)){if prefix.is_some_and(|prefix|total.is_some_and(|total|prefix>=total)){break;}let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());for turn in 0..100000{if prefix==Some(turn){caller.cancel().cancel_now();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&input,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));break;}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).unwrap(){total=Some(turn+1);assert!(prefix.is_none());break;}assert!(turn<99999);}super::set_tests::retire(&mut caller,&mut copy);caller.finish();}assert!(total.is_some());}}
